(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ContextMenuModel=api})(typeof globalThis!=='undefined'?globalThis:this,function(){'use strict';function fail(c){throw Object.assign(new Error(c),{code:c})}function ident(s){if(typeof s!=='string'||!/^[A-Za-z0-9_-]{1,64}$/.test(s))fail('INVALID_CONTEXT');return s}function validate(v){if(!v||v.version!==1||!['link','image','video'].includes(v.kind)||typeof v.title!=='string'||v.title.length>160||typeof v.protected!=='boolean'||typeof v.canDownload!=='boolean'||typeof v.canSaveImage!=='boolean'||typeof v.url!=='string'||v.url.length>2048||/[\x00-\x20\x7f]/.test(v.url))fail('INVALID_CONTEXT');let u;try{u=new URL(v.url)}catch(_){fail('INVALID_URL')}if(!['http:','https:'].includes(u.protocol)||u.username||u.password)fail('INVALID_URL');return{version:1,contextId:ident(v.contextId),navigationEpoch:ident(v.navigationEpoch),kind:v.kind,title:v.title,url:u.href,protected:v.protected,canDownload:v.canDownload,canSaveImage:v.canSaveImage}}
function actions(v){v=validate(v);return[{id:'open',label:'Open in new tab',enabled:true},{id:'downloads',label:'Send to Downloads',enabled:v.canDownload&&!v.protected},{id:'copy',label:'Copy link',enabled:true},...(v.kind==='image'?[{id:'save-image',label:'Save image to USB',enabled:v.canSaveImage&&!v.protected}]:[]),{id:'qr',label:'Share via QR',enabled:v.url.length<=1024}]}
function request(v,action){v=validate(v);if(!actions(v).some(a=>a.id===action&&a.enabled))fail('UNAVAILABLE_ACTION');const method={open:'context.openTab',downloads:'context.sendDownloads',copy:'context.copyLink','save-image':'context.saveImage'}[action];if(!method)fail('LOCAL_ACTION');return{method,params:{contextId:v.contextId,navigationEpoch:v.navigationEpoch}}}return Object.freeze({validate,actions,request});});
